#!/bin/sh
# Data/Request and ordinary Capability slices. Full API/facility/Corpus parity
# and non-yielding concurrent admission remain later gates.
set -eu
cd "$(dirname "$0")"
selection='^(TestZigBackend.*|TestRequestExecutionAndWorkerRefusals|TestFailedInitialiserHasItsInstructionPosition|TestMailboxReservationIncludesQueuedInputs|TestSliceDebtAndPumpRoundRobin|TestPumpAcceptsClockBoundariesAndRefusesDecrease|TestWaitReleasesScriptAndResumesAfterInputs|TestRunawayScriptFaultPreservesOtherScriptsAndCommittedSegments|TestWaitFuelFaultDoesNotChargeOrInstallTimer|TestOverrideRejectsUnknownPresenceBits|TestCallChargeAndResultConversionBoundaries|TestOperationValidFailureData|TestOperationFailureConversionLimits|TestSuspendingOperationQueuesAnAnswerDuringStart|TestSuspendingOperationWorkerSettlementsAndRevocation|TestSuspendingOperationFailuresAndResumeLimits|TestSuspendingOperationTimeoutAndCancellation|TestCapabilityJoinUsesMemberDeadlinesAndFirstFailure|TestCapabilityJoinKeepsEarlySettlementsAcrossBodyPreemption|TestLateCapabilityFaultPreservesEarlierSegments|TestCapabilityReadyAnswerRetentionAndCap|TestCancelRunAtStartRollsBackAndAbandons|TestSuspendingPrechargeAndRetentionFaults)$'
exec go test -tags talk_zig_experimental -run "$selection" -count=1 "$@" .
